from pathlib import Path
import json
D=Path(__file__).resolve().parent
M=json.loads((D/'manifest.json').read_text())
R={r['name']:r for r in M['rounds']}
items=[]
F='/next/foundations/blueprint'
P='/next/components/agent-components/'
def add(round,needle,category,key,criterion,route=F,probe=None,selector=None,refs=None):
    source=R[round]['sources'][0]
    lines=[x for x in R[round]['checklist'] if needle in x['text']]
    if not lines:raise ValueError((round,needle))
    items.append(dict(id=f'{round.replace("/","-")}-{key}',round=round,source=source,lines=[x['line'] for x in lines],original=[x['text'] for x in lines],category=category,criterion=criterion,route=route,probe=probe,selector=selector,refs=refs or []))
def A(r,n,k,c,route=F,probe=None):add(r,n,'可自动化',k,c,route,probe or k)
def V(r,n,k,c,route=F,probe=None,selector='main'):add(r,n,'需目检',k,c,route,probe,selector)
def C(r,n,k,c,refs=None):add(r,n,'不适用或已被其他项覆盖',k,c,refs=refs)
